// FILES is generated by tools/prepare_cloudflare.py from the checked Web export.
function negotiateEncoding(request, file) {
  const encodings = file.encodings || {};
  const accept = (request.headers.get('Accept-Encoding') || '').toLowerCase();
  if (encodings.br && /\bbr\b/.test(accept)) return ['br', encodings.br];
  if (encodings.gzip && /\bgzip\b/.test(accept)) return ['gzip', encodings.gzip];
  return [null, { parts: file.parts, size: file.size, sha256: file.sha256 }];
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const file = FILES[url.pathname];
    if (!file) return env.ASSETS.fetch(request);
    if (request.method !== 'GET' && request.method !== 'HEAD') {
      return new Response('Method not allowed', { status: 405 });
    }
    const [encoding, variant] = negotiateEncoding(request, file);
    const etag = '"' + variant.sha256 + (encoding ? '-' + encoding : '') + '"';
    const headers = {
      'Content-Type': file.type,
      'Content-Length': String(variant.size),
      'Cache-Control': file.cache_control || 'public, max-age=0, must-revalidate',
      'ETag': etag,
      'Vary': 'Accept-Encoding',
    };
    if (encoding) headers['Content-Encoding'] = encoding;
    const validators = (request.headers.get('If-None-Match') || '')
      .split(',').map(value => value.trim().replace(/^W\//, ''));
    if (validators.includes(etag) || validators.includes('*')) {
      return new Response(null, { status: 304, headers: { ETag: etag, Vary: 'Accept-Encoding' } });
    }
    if (request.method === 'HEAD') return new Response(null, { headers });
    // Single static asset fast-path avoids TransformStream overhead when size <= 24 MiB.
    if (variant.parts.length === 1 && variant.parts[0] !== url.pathname) {
      const asset = await env.ASSETS.fetch(new Request(new URL(variant.parts[0], url)));
      if (!asset.ok || !asset.body) return new Response('Missing asset', { status: 502 });
      return new Response(asset.body, { headers });
    }
    if (variant.parts.length === 1 && variant.parts[0] === url.pathname) {
      const asset = await env.ASSETS.fetch(new Request(url));
      if (!asset.ok || !asset.body) return new Response('Missing asset', { status: 502 });
      return new Response(asset.body, { headers });
    }
    const { readable, writable } = typeof FixedLengthStream === 'function'
      ? new FixedLengthStream(variant.size) : new TransformStream();
    const pipeline = (async () => {
      try {
        for (const path of variant.parts) {
          const response = await env.ASSETS.fetch(new Request(new URL(path, url)));
          if (!response.ok || !response.body) throw new Error('Missing asset part');
          await response.body.pipeTo(writable, { preventClose: true });
        }
        await writable.close();
      } catch (error) {
        await writable.abort(error).catch(() => {});
        throw error;
      }
    })();
    if (ctx) ctx.waitUntil(pipeline);
    else void pipeline.catch(() => {});
    return new Response(readable, { headers });
  },
};
